<?phpclass Index_model extends CI_Model {    function __construct() {        parent::__construct();    }    function get_phone_value($phone) {        return $this->db->select('*')                        ->from(TBL_DRIVERS)->where('phone', $phone)->get()->row_object();    }    function get_active_phone_value($phone) {        return $this->db->select('*')                        ->from(TBL_DRIVERS)->where('phone', $phone)->where('status', '1')->get()->row_object();    }    function insertDriver($data) {        $this->db->insert(TBL_DRIVERS, $data);        $insert_id = $this->db->insert_id();        return $insert_id;    }    function phone_exist_except_self($user_id, $phone) {        return $this->db->select('*')                        ->from(TBL_DRIVERS)->where('phone', $phone)->where('driver_id <>', $user_id)->get()->row_object();    }    function updateDriver($driver_id, $updateData = array()) {        $this->db->where('driver_id', $driver_id);        $result = $this->db->update(TBL_DRIVERS, $updateData);        return $result;    }    function get_user_value($user_id) {        return $this->db->select('*')                        ->from(TBL_DRIVERS)->where('driver_id', $user_id)->where('status', '1')->get()->row_object();    }}